 +AU_L(50,280,590,280,AU_AX,3)+[0,10,20,30].map(a=>AU_L(50+18*a,280,50+18*a,290,AU_AX,2)+AU_T(50+18*a,316,a+' A',{fs:22,a:'middle',fill:AU_GREY})).join('')
