 +AU_L(350,250,480,250,ORG,9)+`<circle cx="520" cy="250" r="34" fill="#FFF4CC" stroke="${ORG}" stroke-width="4"/>`+AU_T(520,258,'load',{fs:22,fw:700,a:'middle',fill:ORG})
