 ICON.auDialH=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${AU_box(0,0,380,160,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}${AU_T(20,36,'cranking speed',{fs:24,fw:800,fill:BLU})}
  <rect x="20" y="56" width="${(340*275/300).toFixed(1)}" height="34" rx="6" fill="${BLU}" fill-opacity=".8"/>${AU_T(30,82,'warm 275 rpm',{fs:22,fw:800,fill:'#FFFFFF'})}
  <rect x="20" y="104" width="${(340*100/300).toFixed(1)}" height="34" rx="6" fill="${RED}" fill-opacity=".8"/>${AU_T(143,130,'cold 100 rpm',{fs:22,fw:800,fill:RED})}</g>`;
 ICON.auBattH=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${AU_box(0,0,380,160,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}${AU_T(20,36,'battery voltage',{fs:24,fw:800,fill:ORG})}
  ${AU_batt(52,60)}${AU_T(100,82,'at rest: 12.6 V',{fs:24,fw:800,fill:INK})}${AU_T(100,122,'cranking: 9.6 V',{fs:24,fw:800,fill:RED})}${AU_T(100,148,'300 A × 0.01 Ω = 3 V lost',{fs:20,fill:AU_GREY})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.auCrossI=(x,y)=>{const X0=20,X1=400,YB=290,YT=40,pw=AU_cross(...AU_WARM),pc=AU_cross(...AU_COLD);
  return `<g transform="translate(${x-210} ${y-165})">${AU_L(X0,YB,X1,YB,AU_AX,3)}${AU_L(X0,YB,X0,YT,AU_AX,3)}
  <rect x="${X0}" y="${YT}" width="${(AU_px(80,X0,X1,320)-X0).toFixed(1)}" height="${YB-YT}" fill="${GRN}" fill-opacity=".15"/>
  ${AU_WARM.map((l,i)=>AU_tline(...l,X0,X1,320,YB,YT,70,BLU,5,i?'10 7':'')).join('')}${AU_COLD.map((l,i)=>AU_tline(...l,X0,X1,320,YB,YT,70,RED,5,i?'10 7':'')).join('')}
  ${AU_dot(AU_px(pw[0],X0,X1,320),AU_py(pw[1],YB,YT,70),BLU,11)}${AU_dot(AU_px(pc[0],X0,X1,320),AU_py(pc[1],YB,YT,70),RED,11)}
  ${AU_T(AU_px(pw[0],X0,X1,320),AU_py(pw[1],YB,YT,70)-22,'275',{fs:28,fw:800,a:'middle',fill:BLU})}${AU_T(AU_px(pc[0],X0,X1,320),AU_py(pc[1],YB,YT,70)+46,'100',{fs:28,fw:800,a:'middle',fill:RED})}
  ${AU_T(X0+8,YB+34,'below 80 rpm: no start',{fs:24,fw:700,fill:GRN})}</g>`};
 ICON.auStartI=(x,y)=>`<g transform="translate(${x-210} ${y-165})">
  ${AU_T(10,44,'key',{fs:26,fw:800})}${AU_L(70,36,140,36,INK,2)}<rect x="140" y="18" width="80" height="36" rx="6" fill="#FFFFFF" stroke="${BLU}" stroke-width="3"/>${AU_T(180,82,'relay 0.2 A',{fs:24,fw:800,a:'middle',fill:BLU})}
  ${AU_L(220,36,270,36,GRN,3)}<rect x="270" y="14" width="140" height="44" rx="8" fill="${GRN}" fill-opacity=".2" stroke="${GRN}" stroke-width="3"/>${AU_T(340,82,'solenoid 40 A',{fs:24,fw:800,a:'middle',fill:GRN})}
  ${AU_batt(40,190)}${AU_L(40,190,40,140,ORG,9)}${AU_L(40,140,250,140,ORG,9)}<circle cx="250" cy="140" r="7" fill="${INK}"/><circle cx="320" cy="140" r="7" fill="${INK}"/>${AU_L(250,156,320,156,INK,6)}
  ${AU_L(285,94,285,150,GRN,2,'stroke-dasharray="6 5"')}${AU_L(320,140,380,140,ORG,9)}${AU_L(380,140,380,196,ORG,9)}${AU_motor(380,226,ORG)}
  ${AU_T(150,128,'30',{fs:24,fw:800,a:'middle',fill:ORG})}${AU_T(10,310,'250 A to the motor',{fs:30,fw:800,fill:ORG})}</g>`;
